sem = asyncio.Semaphore(10)  # at most 10 calls in the air

async def ask_limited(prompt: str) -> str:
    async with sem:
        return await ask(prompt)

async def fetch_all(prompts: list[str]) -> list[str]:
    return await asyncio.gather(*(ask_limited(p) for p in prompts))

