from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class ChatRequest(BaseModel):
    user_id: str
    prompt: str = Field(min_length=1, max_length=8000)

@app.post("/chat")
async def chat(req: ChatRequest) -> dict:
    return {"answer": f"echo: {req.prompt[:50]}"}

from fastapi import Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

@app.exception_handler(RequestValidationError)
async def on_invalid(request: Request, exc: RequestValidationError):
    first = exc.errors()[0]
    field = ".".join(str(p) for p in first["loc"][1:])
    return JSONResponse(status_code=422, content={
        "error": {"code": "invalid_request", "message": f"{field}: {first['msg']}"}
    })

import asyncio, random
import httpx

async def call_model(client: httpx.AsyncClient, prompt: str, key: str) -> dict:
    for attempt in range(4):  # 1 try + up to 3 retries
        try:
            r = await client.post("/v1/generate", json={"prompt": prompt},
                                  headers={"Idempotency-Key": key}, timeout=2.0)
            if r.status_code < 400:
                return r.json()
            if r.status_code != 429 and r.status_code < 500:
                r.raise_for_status()  # 400, 401, 404...: never retry
        except httpx.TransportError:  # includes timeouts
            pass
        if attempt < 3:
            await asyncio.sleep(random.uniform(0, min(8.0, 0.5 * 2 ** attempt)))
    raise RuntimeError("model call failed after 3 retries")

